// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadLora = makeLoadFont('Lora');
const loadInter = makeLoadFont('Inter');

const { fontFamily: loraFamily } = loadLora();
const { fontFamily: interFamily } = loadInter();



export type ResearchPreviewProps = Record<string, any>;

const ResearchPreview: React.FC<ResearchPreviewProps> = ({
  text = "Now available as a research preview",
  phoneText = "Can you open the Acme landing page proposal in my downloads and give me the key points? I have like 15 min before I need to present it!",
  backgroundColor = "#d4c9b8",
  textColor = "#121212",
  transparentBackground = false,
  durationInSeconds = 8,
  phoneOffsetY = 0,
  chatBoxOffsetY = 0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const s = Math.min(width, height);

  // Split text into words to animate them individually
  const words = text.split(" ");

  // --- TIMING CALCULATIONS ---
  const totalFrames = durationInSeconds * fps;
  const textEntranceEnd = (words.length > 0 ? words.length - 1 : 0) * 4 + 35;
  
  const phoneSlideStart = textEntranceEnd + 10;
  const phoneSlideDuration = 30;
  const phoneSlideEnd = phoneSlideStart + phoneSlideDuration;

  const typeStart = phoneSlideEnd + 15;
  
  // Scale typing to fit remaining duration but leave time for final send animation
  const typeEnd = Math.max(typeStart + 10, totalFrames - 60); 
  const clickStart = typeEnd + 10;
  const sendStart = clickStart + 10;

  // --- RESPONSIVE PHONE DIMENSIONS ---
  const isHorizontal = width > height;
  // Make the phone fill a significant portion of the width
  const phoneWidth = isHorizontal ? width * 0.45 : width * 0.85;
  // Crop slightly at top and bottom (10% taller than the frame)
  const phoneHeight = height * 1.1; 
  const verticalCrop = (phoneHeight - height) / 2;

  // Scale internal elements based on the new, wider phone dimensions
  const ps = phoneWidth / 0.6;

  // --- ANIMATIONS ---
  const containerScale = interpolate(
    frame,
    [0, totalFrames],
    [1, 1.04],
    { extrapolateRight: "clamp" }
  );

  const textContainerOpacity = interpolate(
    frame,
    [phoneSlideStart, phoneSlideStart + 15],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const phoneTranslateY = interpolate(
    frame,
    [phoneSlideStart, phoneSlideEnd],
    [height / 2 + phoneHeight / 2, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    }
  );

  const typeProgress = interpolate(
    frame,
    [typeStart, typeEnd],
    [0, phoneText.length],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const charactersToType = Math.floor(typeProgress);
  const typedText = phoneText.slice(0, charactersToType);

  const isTypingActive = frame >= typeStart && frame < sendStart;
  const cursorOpacity = Math.floor(frame / 15) % 2 === 0 && isTypingActive ? 1 : 0;

  // Click & Send Animations
  const buttonScale = interpolate(
    frame,
    [clickStart, clickStart + 5, clickStart + 10],
    [1, 0.85, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const isSent = frame >= sendStart;

  const bubbleSpring = spring({
    frame: frame - sendStart,
    fps,
    config: { damping: 14, stiffness: 120 },
  });

  const bubbleOpacity = interpolate(
    frame,
    [sendStart, sendStart + 5],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Background Text Overlay */}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "center",
          width: "90%",
          maxWidth: `${s * 2}px`,
          gap: `${s * 0.018}px`,
          transform: `scale(${containerScale})`,
          opacity: textContainerOpacity,
          fontFamily: loraFamily,
        }}
      >
        {words.map((word, i) => {
          const startFrame = i * 4;
          const progress = interpolate(
            frame,
            [startFrame, startFrame + 35],
            [0, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.out(Easing.cubic),
            }
          );

          const opacity = progress;
          const translateY = interpolate(progress, [0, 1], [30, 0]);
          const blurVal = interpolate(progress, [0, 1], [10, 0]);

          return (
            <span
              key={i}
              style={{
                color: textColor,
                fontSize: `${s * 0.075}px`,
                fontWeight: 400,
                letterSpacing: "-0.01em",
                opacity,
                transform: `translateY(${translateY}px)`,
                filter: `blur(${blurVal}px)`,
                display: "inline-block",
              }}
            >
              {word}
            </span>
          );
        })}
      </div>

      {/* Phone Mockup */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: `${phoneWidth}px`,
          height: `${phoneHeight}px`,
          backgroundColor: "#FDFCFB",
          borderRadius: `${ps * 0.07}px`,
          border: `${ps * 0.012}px solid #F9F8F6`,
          boxShadow: "0 20px 60px rgba(0,0,0,0.06)",
          display: "flex",
          flexDirection: "column",
          fontFamily: interFamily,
          overflow: "hidden",
          transform: `translate(-50%, calc(-50% + ${phoneTranslateY}px + ${phoneOffsetY}px))`,
          zIndex: 10,
        }}
      >
        {/* Decorative Grid & Warm Glow */}
        <div style={{ position: "absolute", inset: 0, zIndex: 0, pointerEvents: "none" }}>
          <svg width="100%" height="100%" style={{ opacity: 0.5 }}>
            <pattern id="phoneGrid" width={ps * 0.03} height={ps * 0.03} patternUnits="userSpaceOnUse">
              <path d={`M ${ps * 0.03} 0 L 0 0 0 ${ps * 0.03}`} fill="none" stroke="#EAE8E4" strokeWidth="1" />
            </pattern>
            <rect width="100%" height="100%" fill="url(#phoneGrid)" />
          </svg>
          <div
            style={{
              position: "absolute",
              bottom: 0, left: 0, right: 0,
              height: "60%",
              background: "radial-gradient(100% 100% at 50% 100%, rgba(202, 139, 109, 0.1) 0%, rgba(253, 252, 251, 0) 100%)",
            }}
          />
        </div>

        {/* Header Area */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            paddingTop: `calc(${verticalCrop}px + ${ps * 0.025}px)`, // Offset for crop
            paddingBottom: `${ps * 0.025}px`,
            paddingLeft: `${ps * 0.03}px`,
            paddingRight: `${ps * 0.03}px`,
            position: "relative",
            zIndex: 1,
          }}
        >
          {/* Hamburger Menu */}
          <div
            style={{
              width: `${ps * 0.038}px`,
              height: `${ps * 0.038}px`,
              borderRadius: `${ps * 0.019}px`,
              backgroundColor: "#FFFFFF",
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              gap: `${ps * 0.004}px`,
              boxShadow: "0 2px 8px rgba(0,0,0,0.03)",
            }}
          >
            <div style={{ width: `${ps * 0.016}px`, height: `${ps * 0.002}px`, backgroundColor: "#333", borderRadius: "2px" }} />
            <div style={{ width: `${ps * 0.016}px`, height: `${ps * 0.002}px`, backgroundColor: "#333", borderRadius: "2px" }} />
            <div style={{ width: `${ps * 0.016}px`, height: `${ps * 0.002}px`, backgroundColor: "#333", borderRadius: "2px" }} />
          </div>

          {/* Title Area */}
          <div style={{ flex: 1, textAlign: "center", marginRight: `${ps * 0.038}px` }}>
            <div style={{ fontSize: `${ps * 0.021}px`, fontWeight: 500, color: "#111" }}>
              Cowork dispatch
            </div>
            <div
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: `${ps * 0.004}px`,
                backgroundColor: "#E8F4EC",
                padding: `${ps * 0.003}px ${ps * 0.008}px`,
                borderRadius: `${ps * 0.01}px`,
                marginTop: `${ps * 0.004}px`,
              }}
            >
              <div style={{ width: `${ps * 0.006}px`, height: `${ps * 0.006}px`, borderRadius: "50%", backgroundColor: "#4CAF50" }} />
              <div style={{ fontSize: `${ps * 0.012}px`, color: "#4CAF50", fontWeight: 600 }}>Online</div>
            </div>
          </div>
        </div>

        {/* Spacer to push content to the bottom */}
        <div style={{ flex: 1 }} />

        {/* Container for Chat Bubble and Prompt Box to adjust Y position together */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            width: "100%",
            transform: `translateY(${chatBoxOffsetY}px)`,
          }}
        >
          {/* Sent Chat Bubble Container */}
          {isSent && (
            <div
              style={{
                alignSelf: "flex-end",
                margin: `0 ${ps * 0.025}px ${ps * 0.02}px ${ps * 0.15}px`,
                maxWidth: "85%",
                backgroundColor: "#C66B4F",
                borderRadius: `${ps * 0.03}px ${ps * 0.03}px ${ps * 0.008}px ${ps * 0.03}px`,
                padding: `${ps * 0.022}px ${ps * 0.025}px`,
                boxShadow: "0 4px 15px rgba(0,0,0,0.05)",
                opacity: bubbleOpacity,
                transform: `scale(${bubbleSpring})`,
                transformOrigin: "bottom right",
                zIndex: 2,
              }}
            >
              <div
                style={{
                  color: "#FFFFFF",
                  fontSize: `${ps * 0.018}px`,
                  lineHeight: 1.45,
                }}
              >
                {phoneText}
              </div>
            </div>
          )}

          {/* Prompt Box */}
          <div
            style={{
              marginLeft: `${ps * 0.025}px`,
              marginRight: `${ps * 0.025}px`,
              // Add vertical crop offset to ensure input area remains visible
              marginBottom: `calc(${verticalCrop}px + ${ps * 0.025}px)`,
              background: "linear-gradient(160deg, #FFF4F0 0%, #FDE0D8 100%)", // Warm peach/salmon gradient
              borderRadius: `${ps * 0.03}px`,
              padding: `${ps * 0.022}px ${ps * 0.025}px`,
              boxShadow: "0 4px 25px rgba(0,0,0,0.04)",
              zIndex: 1,
              display: "flex",
              flexDirection: "column",
            }}
          >
            {/* Text Content */}
            <div
              style={{
                minHeight: isSent ? undefined : `${ps * 0.08}px`,
                fontSize: `${ps * 0.018}px`,
                lineHeight: 1.45,
                color: isSent ? "#888888" : "#1A1A1A",
                marginBottom: `${ps * 0.015}px`,
              }}
            >
              {isSent ? "Chat with Cowork" : typedText}
              {!isSent && <span style={{ opacity: cursorOpacity, color: "#C58B71", marginLeft: "2px" }}>|</span>}
            </div>

            {/* Action Icons */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              {/* Plus Icon */}
              <svg
                width={ps * 0.026}
                height={ps * 0.026}
                viewBox="0 0 24 24"
                fill="none"
                stroke="#666"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <line x1="12" y1="5" x2="12" y2="19" />
                <line x1="5" y1="12" x2="19" y2="12" />
              </svg>

              {/* Send Button */}
              <div
                style={{
                  width: `${ps * 0.038}px`,
                  height: `${ps * 0.038}px`,
                  borderRadius: `${ps * 0.019}px`,
                  backgroundColor: isSent ? "#EBBDB0" : "#C58B71",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  transform: `scale(${buttonScale})`,
                  transformOrigin: "center",
                }}
              >
                <svg
                  width={ps * 0.019}
                  height={ps * 0.019}
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="white"
                  strokeWidth="2.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <line x1="12" y1="19" x2="12" y2="5" />
                  <polyline points="5 12 12 5 19 12" />
                </svg>
              </div>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ResearchPreview;